"""Targeted exam-centre attendance, private contacts, PIN writes and future-date gate."""
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});page.route('**/exam-test',lambda r:r.fulfill(content_type='text/html',body='<meta name=viewport content="width=device-width,initial-scale=1"><link rel=stylesheet href=/cbse.css><link rel=stylesheet href=/cbse-mission-theme.css><main id=root></main>'));page.goto('http://127.0.0.1:8000/exam-test');errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.evaluate("""async()=>{window.m=await import('./cbse-exam-centre-model.js');window.view=await import('./cbse-board-datesheet-view.js');window.draft={"classes": {"X": {"sections": {"a": {"name": "A", "subjects": {"english": {"name": "English", "code": "184"}, "science": {"name": "Science", "code": "086"}}, "students": {"one": {"name": "English Student One", "roll": "101", "subjects": {"english": true}}, "two": {"name": "English Student Two", "roll": "102", "subjects": {"english": true}}, "other": {"name": "Science Only Student", "roll": "103", "subjects": {"science": true}}}}}}}};window.contacts={'X:a:one':{guardian:'Parent One',numbers:{father:{label:'Father',phone:'9876543210'}},location:'Saved home address',mapLocation:'27.1,93.6'},'X:a:two':{guardian:'Parent Two',location:'Second home address'}};window.store={};window.clock=Date.parse('2027-02-26T04:00:00Z');window.calls=[];window.principal=false;window.start=()=>view.renderBoardDateSheet(document.querySelector('#root'),{draft,attendance:{staff:{'X:teacher':{name:'Synthetic Teacher',designation:'TGT',status:'active'}},principal,state:{},read:async scope=>{const paper=m.examCentrePaper(draft,scope);return {ok:true,paper,students:m.examCentreRoster(draft,contacts,paper),records:m.examCentreRecords(store,principal),serverDate:m.examCentreToday(clock),serverTime:clock}},save:async input=>{if(!principal&&input.pin!=='123')throw Error('Incorrect PIN');calls.push(input);store=m.applyExamCentreAttendanceBatch(store,input,{id:principal?'principal':'X:teacher',name:principal?'Principal':'Synthetic Teacher',role:principal?'principal':'staff',status:'active'},m.examCentrePaper(draft,input),clock);return {ok:true,records:m.examCentreRecords(store,principal),serverDate:m.examCentreToday(clock),serverTime:clock}}}});start();}""")
 page.locator('[name=board-standard]').select_option('X');page.locator('[data-exam-date="2027-02-26"]').get_by_role('button',name='Exam-centre attendance',exact=True).click();page.locator('.exam-attendance-row').first.wait_for();assert page.locator('.exam-attendance-row').count()==2;assert page.locator('.exam-attendance-avatar[data-student-photo-mode=avatar]').count()==2;page.evaluate("""async()=>{const {observeStudentPhotos}=await import('./cbse-student-photo.js');const canvas=document.createElement('canvas');canvas.width=24;canvas.height=24;observeStudentPhotos(document.querySelector('#root'),()=>({enabled:true,revision:1,local:{'X:a:one':{dataUrl:canvas.toDataURL('image/png'),width:24,height:24}}}));}""");page.locator('[data-student-photo-key="X:a:one"] img').wait_for();assert 'Science Only Student' not in page.locator('.exam-centre-panel').inner_text();assert page.locator('.exam-centre-contact, [name=exam-attendance-status]').count()==0;assert page.locator('a[href="#student=X%3Aa%3Aone"]').count()==1
 page.locator('[name=exam-attendance-staff]').select_option('X:teacher');page.get_by_role('radio',name='English Student One — Present',exact=True).check();page.get_by_role('radio',name='English Student Two — Absent',exact=True).check();page.get_by_role('button',name='Save attendance · PIN',exact=True).click();page.locator('[name=exam-attendance-pin]').fill('123');page.get_by_role('button',name='Confirm attendance',exact=True).click();page.get_by_text('Attendance saved · 2 students.',exact=True).wait_for();assert page.evaluate('calls.length')==1;assert page.evaluate('calls[0].changes.length')==2;assert page.locator('.exam-attendance-saved-status').all_text_contents()==['Present','Absent'];assert '1 Present · 1 Absent · 0 Unmarked' in page.locator('.exam-centre-totals').inner_text()
 page.get_by_role('radio',name='English Student One — Absent',exact=True).check();page.evaluate("""()=>{const row={exam:'cbse',classId:'X',paperId:'X|2027-02-26|184'};store=m.applyExamCentreAttendance(store,{...row,studentKey:'X:a:one',status:'not-reported',expectedRevision:1,requestId:'other_teacher'}, {id:'other',name:'Other Teacher',role:'staff',status:'active'},m.examCentrePaper(draft,row),clock)}""");page.get_by_role('button',name='Save attendance · PIN',exact=True).click();page.locator('[name=exam-attendance-pin]').fill('123');page.get_by_role('button',name='Confirm attendance',exact=True).click();page.get_by_text('Another staff member updated this student. Refresh attendance before saving.',exact=True).wait_for();page.get_by_role('button',name='Refresh attendance',exact=True).click();page.get_by_text('0 Present · 2 Absent · 0 Unmarked',exact=True).wait_for()
 page.evaluate("""()=>{const row={exam:'cbse',classId:'X',paperId:'X|2027-02-26|184'};store=m.applyExamCentreAttendance(store,{...row,studentKey:'X:a:two',status:'reported',expectedRevision:1,requestId:'live_update_other'}, {id:'other',name:'Other Teacher',role:'staff',status:'active'},m.examCentrePaper(draft,row),clock)}""");page.get_by_text('1 Present · 1 Absent · 0 Unmarked',exact=True).wait_for(timeout=12000)
 for width in [320,390,768,1440]:
  page.set_viewport_size({'width':width,'height':844});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
 page.evaluate("clock=Date.parse('2026-11-08T05:00:00Z');store={};document.querySelector('#root').replaceChildren();start()");page.locator('[name=board-standard]').select_option('X');page.locator('[data-exam-date="2027-02-26"]').get_by_role('button',name='Exam-centre attendance',exact=True).click();page.locator('.exam-attendance-row').first.wait_for();assert page.get_by_role('radio').count()==4 and page.locator('input[type=radio]:enabled').count()==0;assert 'Attendance opens on' in page.locator('.exam-centre-panel').inner_text();assert not errors,errors;b.close()
